snippets/lovenspa-article-jsonld.liquid:
{%- comment -%}
  Love'nSpa : JSON-LD des articles (Article + BreadcrumbList + FAQPage optionnelle)
  ---------------------------------------------------------------------------
  Remplace le bloc JSON-LD "Article" historique de sections/article-template.liquid.
  Usage : {%- render 'lovenspa-article-jsonld', article: article, blog: blog -%}

  - Article : headline, description (global.description_tag > excerpt > début du
    contenu), image (image à la une > custom.image_une > 1re image du body),
    datePublished / dateModified, author, publisher + logo, mainEntityOfPage.
  - BreadcrumbList : Accueil > <titre du blog> > <titre de l'article>.
  - FAQPage : uniquement si le metafield article custom.faq (type json) contient
    un tableau [{"q": "...", "a": "..."}].
  - GARDE DE TRANSITION : si le body de l'article contient déjà un bloc
    application/ld+json (ancien JSON-LD collé à la main), le snippet n'émet RIEN
    pour éviter les doublons. Une fois le JSON-LD retiré du body (phase 2),
    le snippet prend le relais automatiquement.
  - Tout l'échappement passe par le filtre | json.
{%- endcomment -%}

{%- liquid
  assign lns_article = article
  assign lns_blog = blog

  # Garde de transition : le body porte déjà son JSON-LD
  assign lns_body_has_jsonld = false
  if lns_article.content contains 'application/ld+json'
    assign lns_body_has_jsonld = true
  endif
-%}

{%- if lns_body_has_jsonld -%}
  <!-- lovenspa-article-jsonld: JSON-LD present dans le body, emission theme desactivee -->
{%- else -%}
  {%- liquid
    # URLs absolues dérivées du canonical (domaine principal lovenspa.fr)
    assign lns_page_url = canonical_url
    assign lns_origin = canonical_url | split: '/blogs/' | first
    assign lns_home_url = lns_origin | append: '/'
    assign lns_blog_url = lns_origin | append: lns_blog.url

    # Description
    assign lns_description = lns_article.metafields.global.description_tag.value | default: lns_article.metafields.global.description_tag
    if lns_description == blank
      assign lns_description = lns_article.excerpt | strip_html | strip_newlines | strip
    endif
    if lns_description == blank
      assign lns_description = lns_article.content | strip_html | strip_newlines | truncate: 160
    endif

    # Image : image à la une > metafield custom.image_une > 1re <img> du body
    assign lns_image = ''
    if lns_article.image
      assign lns_image = lns_article.image | image_url: width: 1200 | prepend: 'https:'
    elsif lns_article.metafields.custom.image_une.value
      assign lns_image = lns_article.metafields.custom.image_une.value | image_url: width: 1200 | prepend: 'https:'
    elsif lns_article.content contains '<img'
      assign lns_img_chunk = lns_article.content | split: '<img' | slice: 1 | first
      if lns_img_chunk contains 'src="'
        assign lns_image = lns_img_chunk | split: 'src="' | slice: 1 | first | split: '"' | first
      endif
    endif
    if lns_image != blank
      assign lns_image_start = lns_image | slice: 0, 2
      if lns_image_start == '//'
        assign lns_image = lns_image | prepend: 'https:'
      endif
    endif

    # Auteur : la rédaction = Organization, sinon Person
    assign lns_author_name = lns_article.author | strip
    assign lns_author_type = 'Person'
    if lns_author_name == blank
      assign lns_author_name = "La rédaction Love'nSpa"
    endif
    assign lns_author_lc = lns_author_name | downcase
    if lns_author_lc contains 'rédaction' or lns_author_lc contains 'redaction'
      assign lns_author_type = 'Organization'
    endif

    # Logo éditeur : logo de marque Shopify, sinon favicon du thème, sinon URL fixe vérifiée
    assign lns_logo = 'https://lovenspa.fr/cdn/shop/files/Lovenspa_favicon_rond_xl.png'
    if shop.brand.logo
      assign lns_logo = shop.brand.logo | image_url: width: 600 | prepend: 'https:'
    elsif settings.favicon
      assign lns_logo = settings.favicon | image_url: width: 512 | prepend: 'https:'
    endif

    # Rubrique = premier tag
    assign lns_section = lns_article.tags | first

    # FAQ (metafield json custom.faq)
    assign lns_faq = lns_article.metafields.custom.faq.value
    assign lns_faq_count = 0
    if lns_faq != blank
      for lns_item in lns_faq
        if lns_item.q != blank and lns_item.a != blank
          assign lns_faq_count = lns_faq_count | plus: 1
        endif
      endfor
    endif

    assign lns_published = lns_article.published_at | default: lns_article.created_at | date: '%Y-%m-%dT%H:%M:%S%:z'
    assign lns_modified = lns_article.updated_at | default: lns_article.published_at | date: '%Y-%m-%dT%H:%M:%S%:z'
  -%}
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Article",
        "@id": {{ lns_page_url | append: '#article' | json }},
        "headline": {{ lns_article.title | strip_html | truncate: 110 | json }},
        "description": {{ lns_description | json }},
        {%- if lns_image != blank %}
        "image": [{{ lns_image | json }}],
        {%- endif %}
        "datePublished": {{ lns_published | json }},
        "dateModified": {{ lns_modified | json }},
        "inLanguage": "fr-FR",
        {%- if lns_section != blank %}
        "articleSection": {{ lns_section | json }},
        {%- endif %}
        "author": {
          "@type": {{ lns_author_type | json }},
          "name": {{ lns_author_name | json }},
          "url": {{ lns_home_url | json }}
        },
        "publisher": {
          "@type": "Organization",
          "name": "Love'nSpa",
          "url": {{ lns_home_url | json }},
          "logo": {
            "@type": "ImageObject",
            "url": {{ lns_logo | json }}
          }
        },
        "mainEntityOfPage": {
          "@type": "WebPage",
          "@id": {{ lns_page_url | json }}
        },
        "isPartOf": {
          "@type": "Blog",
          "name": {{ lns_blog.title | json }},
          "url": {{ lns_blog_url | json }}
        }
      },
      {
        "@type": "BreadcrumbList",
        "@id": {{ lns_page_url | append: '#breadcrumb' | json }},
        "itemListElement": [
          {
            "@type": "ListItem",
            "position": 1,
            "name": "Accueil",
            "item": {{ lns_home_url | json }}
          },
          {
            "@type": "ListItem",
            "position": 2,
            "name": {{ lns_blog.title | default: 'Magazine' | json }},
            "item": {{ lns_blog_url | json }}
          },
          {
            "@type": "ListItem",
            "position": 3,
            "name": {{ lns_article.title | strip_html | json }},
            "item": {{ lns_page_url | json }}
          }
        ]
      }
      {%- if lns_faq_count > 0 -%}
      ,
      {
        "@type": "FAQPage",
        "@id": {{ lns_page_url | append: '#faq' | json }},
        "mainEntity": [
          {%- assign lns_first = true -%}
          {%- for lns_item in lns_faq -%}
            {%- if lns_item.q != blank and lns_item.a != blank -%}
              {%- unless lns_first -%},{%- endunless -%}
              {%- assign lns_first = false %}
          {
            "@type": "Question",
            "name": {{ lns_item.q | strip_html | strip | json }},
            "acceptedAnswer": {
              "@type": "Answer",
              "text": {{ lns_item.a | strip | json }}
            }
          }
            {%- endif -%}
          {%- endfor %}
        ]
      }
      {%- endif %}
    ]
  }
  </script>
{%- endif -%}

snippets/seo-title.liquid:
{%- liquid
  assign title_norm = page_title | replace: '’', "'" | replace: '‘', "'" | downcase
  assign shop_norm = shop.name | replace: '’', "'" | replace: '‘', "'" | downcase
  assign loven_grid_page_size = 24
  assign loven_page_total = 1
  assign loven_result_count = 0
  if request.page_type == 'collection'
    assign loven_result_count = collection.products_count
  elsif request.page_type == 'search'
    assign loven_result_count = search.results_count
  endif
  if loven_result_count > 0
    assign loven_page_total = loven_result_count | divided_by: loven_grid_page_size
    assign loven_page_mod = loven_result_count | modulo: loven_grid_page_size
    if loven_page_mod > 0
      assign loven_page_total = loven_page_total | plus: 1
    endif
  endif
  if current_page > loven_page_total
    assign loven_page_total = current_page
  endif
-%}
{%- capture seo_title -%}
  {%- if request.page_type == 'collection' and current_page > 1 -%}
    {{ collection.title }}, {{ 'general.meta.page_n_of' | t: page: current_page, pages: loven_page_total }}
  {%- elsif request.page_type == 'search' and current_page > 1 -%}
    {{ page_title }}, {{ 'general.meta.page_n_of' | t: page: current_page, pages: loven_page_total }}
  {%- else -%}
    {%- if template == 'product' -%} Love Room {%  endif %}
    {{ page_title }}
    {%- if current_tags -%}
      {%- assign meta_tags = current_tags | join: ', ' %} &ndash; {{ 'general.meta.tags' | t: tags: meta_tags -}}
    {%- endif -%}
    {%- if current_page != 1 -%}
      &ndash; {{ 'general.meta.page' | t: page: current_page }}
    {%- endif -%}
    {%- if template == 'password' -%}
      {{ shop.name }}
    {%- else -%}
      {%- unless title_norm contains shop_norm -%}
        {%- if template == 'product' -%} | réservez sur {{ shop.name }}{% else %} | {{ shop.name }}{% endif -%}
      {%- endunless -%}
    {%- endif -%}
  {%- endif -%}
{%- endcapture -%}
<title>{{ seo_title | strip }}</title>

snippets/social-meta-tags.liquid:
